  values ('ME', 'short_answer', 'What mass of sodium chloride is present in 500 ml of a 2.00 M NaCl solution? (3 marks)', 'Moles of NaCl = molarity × volume in litres = 2.00 mol/L × 0.500 L = 1.00 mol. Molar mass of NaCl = 23 + 35.5 = 58.5 g/mol. Mass = 1.00 × 58.5 = 58.5 g of sodium chloride.', null, '[{"point": "Moles = molarity × volume (L) = 2.00 × 0.500 = 1.00 mol", "marks": 1.5}, {"point": "Mass = moles × molar mass = 1.00 × 58.5 = 58.5 g", "marks": 1.5}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
