  values ('ME', 'short_answer', 'What does the term ''memory'' of the immune system mean? (3 marks)', 'Immunological memory is the ability of the immune system to remember an antigen (pathogen) it has met before. During the first exposure, the primary immune response is slow and weak, but besides plasma cells it produces long-lived memory B cells and memory T cells. If the same antigen enters again, these memory cells recognise it quickly and produce a much faster, stronger and longer-lasting secondary (anamnestic) response, often destroying the pathogen before disease develops. This memory is the basis of acquired immunity and of vaccination.', null, '[{"point": "Ability of the immune system to remember a pathogen/ antigen it has met before", "marks": 1}, {"point": "During the first (primary) response, memory B and T cells are formed and persist for years", "marks": 1}, {"point": "On re-exposure they give a faster, stronger secondary (anamnestic) response, often preventing disease; basis of vaccination", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'general-subject-knowledge') and t.slug = 'bio-science-general-subject-knowledge'), (select id from public.exam_papers where code = 'me-technical-2'), 'standard', 3,
